1	package com.example.rebate.service;
2	
3	import com.example.rebate.domain.BatchStatus;
4	import com.example.rebate.domain.ChargebackBalance;
5	import com.example.rebate.domain.ChargebackOrder;
6	import com.example.rebate.domain.ChargebackStatus;
7	import com.example.rebate.domain.CheckDetail;
8	import com.example.rebate.domain.ClawbackDetail;
9	import com.example.rebate.domain.ClawbackReceipt;
10	import com.example.rebate.domain.ClawbackStatus;
11	import com.example.rebate.repo.BatchRepository;
12	import com.example.rebate.domain.DeclarationBatch;
13	import com.example.rebate.repo.ChargebackBalanceRepository;
14	import com.example.rebate.repo.ChargebackOrderRepository;
15	import com.example.rebate.repo.CheckDetailRepository;
16	import com.example.rebate.repo.ClawbackDetailRepository;
17	import com.example.rebate.repo.ClawbackReceiptRepository;
18	import com.example.rebate.support.TimeService;
19	import com.example.rebate.web.BadRequestException;
20	import com.example.rebate.web.ConflictException;
21	import com.example.rebate.web.NotFoundException;
22	import com.example.rebate.web.UnprocessableException;
23	import com.example.rebate.web.dto.ChargebackBalanceView;
24	import com.example.rebate.web.dto.ChargebackSubmitRequest;
25	import com.example.rebate.web.dto.ChargebackReviewRequest;
26	import com.example.rebate.web.dto.ChargebackView;
27	import com.example.rebate.web.dto.ClawbackReceiptRequest;
28	import com.example.rebate.web.dto.ClawbackView;
29	import java.math.BigDecimal;
30	import java.math.RoundingMode;
31	import java.time.Instant;
32	import java.util.List;
33	import java.util.Map;
34	import org.springframework.dao.DuplicateKeyException;
35	import org.springframework.stereotype.Service;
36	import org.springframework.transaction.annotation.Transactional;
37	
38	/**
39	 * 结案后分批冲回与追缴。
40	 *
41	 * <p>只引用已结案批次内一张报关单及其冻结退税额，不修改原文库版本、核销流水或结案总额；
42	 * 原批次始终保持 CLOSED。批准在同一事务内以条件更新占用剩余可冲额并产生独立追缴明细，
43	 * 驳回不占额；追缴回执支持多笔部分到账、同流水幂等、异金额拒绝。</p>
44	 */
45	@Service
46	public class ChargebackService {
47	
48	    private final BatchRepository batchRepo;
49	    private final CheckDetailRepository detailRepo;
50	    private final ChargebackBalanceRepository balanceRepo;
51	    private final ChargebackOrderRepository orderRepo;
52	    private final ClawbackDetailRepository clawbackRepo;
53	    private final ClawbackReceiptRepository receiptRepo;
54	    private final TimeService timeService;
55	
56	    public ChargebackService(BatchRepository batchRepo,
57	                             CheckDetailRepository detailRepo,
58	                             ChargebackBalanceRepository balanceRepo,
59	                             ChargebackOrderRepository orderRepo,
60	                             ClawbackDetailRepository clawbackRepo,
61	                             ClawbackReceiptRepository receiptRepo,
62	                             TimeService timeService) {
63	        this.batchRepo = batchRepo;
64	        this.detailRepo = detailRepo;
65	        this.balanceRepo = balanceRepo;
66	        this.orderRepo = orderRepo;
67	        this.clawbackRepo = clawbackRepo;
68	        this.receiptRepo = receiptRepo;
69	        this.timeService = timeService;
70	    }
71	
72	    /**
73	     * 提交冲回单（初版 PENDING，version=1）。同批次同更正编号最多一单；
74	     * 累计（已批准占用 + 本单）不得超过冻结退税额，恰归零合法。
75	     */
76	    @Transactional
77	    public ChargebackView submit(String batchNo, ChargebackSubmitRequest req) {
78	        DeclarationBatch batch = loadClosedBatch(batchNo);
79	        CheckDetail detail = findBatchDetail(batch.id(), req.declarationNo());
80	        Instant now = timeService.now();
81	
82	        if (orderRepo.findByBatchIdAndCorrectionNo(batch.id(), req.correctionNo()).isPresent()) {
83	            throw new ConflictException("同批次更正编号已存在: " + req.correctionNo());
84	        }
85	
86	        long frozenCents = frozenCents(detail);
87	        ChargebackBalance balance = balanceRepo.find(batch.id(), req.declarationNo())
88	                .orElseGet(() -> createBalance(batch.id(), req.declarationNo(), frozenCents, now));
89	        if (req.amountCents() > balance.remainingCents()) {
90	            throw new UnprocessableException(String.format(
91	                    "冲回金额 %,d 分超过剩余可冲额 %,d 分（冻结 %,d 分，已占用 %,d 分）",
92	                    req.amountCents(), balance.remainingCents(),
93	                    balance.frozenCents(), balance.occupiedCents()));
94	        }
95	
96	        ChargebackOrder order = new ChargebackOrder(null, batch.id(), detail.id(),
97	                req.declarationNo(), req.correctionNo(), req.reason(), req.amountCents(),
98	                ChargebackStatus.PENDING, req.submitter(), null, 1, now, null, now, now);
99	        long orderId;
100	        try {
101	            orderId = orderRepo.insert(order);
102	        } catch (DuplicateKeyException e) {
103	            throw new ConflictException("同批次更正编号已存在: " + req.correctionNo());
104	        }
105	        return view(batch, orderRepo.findById(orderId).orElseThrow());
106	    }
107	
108	    /**
109	     * 复核：APPROVE 批准（同事务占用余额并产生追缴明细）或 REJECT 驳回（不占额）。
110	     * 复核人必须不同于提交人；携带 expectedVersion 做乐观并发控制。
111	     */
112	    @Transactional
113	    public ChargebackView review(String batchNo, String correctionNo, ChargebackReviewRequest req) {
114	        DeclarationBatch batch = loadClosedBatch(batchNo);
115	        ChargebackOrder order = loadOrder(batch, correctionNo);
116	        boolean approve = switch (req.action()) {
117	            case "APPROVE" -> true;
118	            case "REJECT" -> false;
119	            default -> throw new BadRequestException("非法复核动作: " + req.action()
120	                    + "（仅支持 APPROVE/REJECT）");
121	        };
122	        if (order.status() != ChargebackStatus.PENDING) {
123	            throw new ConflictException("冲回单当前状态 " + order.status() + "，不可重复复核");
124	        }
125	        if (order.version() != req.expectedVersion()) {
126	            throw new ConflictException("expectedVersion=" + req.expectedVersion()
127	                    + " 与当前版本 " + order.version() + " 不匹配");
128	        }
129	        if (order.submitter().equals(req.reviewer())) {
130	            throw new UnprocessableException("复核人必须不同于提交人: " + req.reviewer());
131	        }
132	
133	        Instant now = timeService.now();
134	        ChargebackStatus target = approve ? ChargebackStatus.APPROVED : ChargebackStatus.REJECTED;
135	        int updated = orderRepo.casReview(order.id(), target, req.reviewer(),
136	                req.expectedVersion(), now);
137	        if (updated == 0) {
138	            throw new ConflictException("冲回单已被并发复核或版本已变化");
139	        }
140	
141	        if (approve) {
142	            // 条件占用：累计不超冻结才生效；并发两笔批准由此串行且不得超冲。
143	            int occupied = balanceRepo.tryOccupy(
144	                    batch.id(), order.declarationNo(), order.amountCents(), now);
145	            if (occupied == 0) {
146	                throw new UnprocessableException("剩余可冲额不足，批准失败");
147	            }
148	            String clawbackNo = clawbackRepo.nextClawbackNo();
149	            ClawbackDetail detail = new ClawbackDetail(null, order.id(), batch.id(), clawbackNo,
150	                    order.amountCents(), 0L, ClawbackStatus.COLLECTING, 1, now, null);
151	            clawbackRepo.insert(detail);
152	        }
153	        return view(batch, orderRepo.findById(order.id()).orElseThrow());
154	    }
155	
156	    /**
157	     * 登记追缴到账回执。仅已批准冲回单可登记；可多笔部分到账，累计不超批准金额，恰收齐转完成；
158	     * 同流水同金额幂等返回，同流水异金额拒绝；完成后只读；乱序到账不改变总额。
159	     */
160	    @Transactional
161	    public ChargebackView registerReceipt(String batchNo, String correctionNo,
162	                                          ClawbackReceiptRequest req) {
163	        DeclarationBatch batch = loadClosedBatch(batchNo);
164	        ChargebackOrder order = loadOrder(batch, correctionNo);
165	        if (order.status() != ChargebackStatus.APPROVED) {
166	            throw new UnprocessableException("未批准冲回单不能登记追缴回执，当前状态 "
167	                    + order.status());
168	        }
169	        ClawbackDetail detail = clawbackRepo.findByOrderId(order.id())
170	                .orElseThrow(() -> new UnprocessableException("追缴明细不存在"));
171	
172	        // 流水号已存在：同金额视为重复回执（乱序/重放，不改总额），异金额拒绝。
173	        List<ClawbackReceipt> sameSerial = receiptRepo.findBySerial(req.receiptSerial());
174	        if (!sameSerial.isEmpty()) {
175	            ClawbackReceipt prior = sameSerial.get(0);
176	            if (prior.receivedCents() != req.receivedCents()) {
177	                throw new ConflictException(String.format(
178	                        "追缴流水号 %s 已登记金额 %,d 分，与本次 %,d 分不一致",
179	                        req.receiptSerial(), prior.receivedCents(), req.receivedCents()));
180	            }
181	            return view(batch, order);
182	        }
183	
184	        if (detail.status() == ClawbackStatus.COMPLETED) {
185	            throw new UnprocessableException("追缴已完成，回执只读");
186	        }
187	        if (detail.version() != req.expectedVersion()) {
188	            throw new ConflictException("expectedVersion=" + req.expectedVersion()
189	                    + " 与追缴明细当前版本 " + detail.version() + " 不匹配");
190	        }
191	        if (req.receivedCents() > detail.approvedCents() - detail.collectedCents()) {
192	            throw new UnprocessableException(String.format(
193	                    "本笔 %,d 分将使累计到账超过批准金额 %,d 分（已收 %,d 分）",
194	                    req.receivedCents(), detail.approvedCents(), detail.collectedCents()));
195	        }
196	
197	        int updated = clawbackRepo.tryAddReceived(detail.id(), req.receivedCents(),
198	                req.expectedVersion(), timeService.now());
199	        if (updated == 0) {
200	            // 并发下重读以给出准确语义（版本冲突/已完成/超收）。
201	            ClawbackDetail fresh = clawbackRepo.findById(detail.id()).orElseThrow();
202	            if (fresh.status() == ClawbackStatus.COMPLETED) {
203	                throw new UnprocessableException("追缴已完成，回执只读");
204	            }
205	            if (fresh.version() != req.expectedVersion()) {
206	                throw new ConflictException("追缴明细已被并发到账更新，expectedVersion 不匹配");
207	            }
208	            throw new UnprocessableException("累计到账不得超过批准金额");
209	        }
210	
211	        ClawbackDetail updatedDetail = clawbackRepo.findById(detail.id()).orElseThrow();
212	        ClawbackReceipt receipt = new ClawbackReceipt(null, updatedDetail.id(), order.id(),
213	                req.receiptSerial(), req.receivedCents(), req.receivedAt(), timeService.now());
214	        receiptRepo.insert(receipt);
215	        return view(batch, order);
216	    }
217	
218	    /**
219	     * 查询单笔冲回单（含余额与追缴明细、回执）。
220	     */
221	    @Transactional(readOnly = true)
222	    public ChargebackView getOrder(String batchNo, String correctionNo) {
223	        DeclarationBatch batch = batchRepo.findByNo(batchNo)
224	                .orElseThrow(() -> new NotFoundException("批次不存在: " + batchNo));
225	        return view(batch, loadOrder(batch, correctionNo));
226	    }
227	
228	    /**
229	     * 逐单冲回余额查询：返回结案批次内每张报关单的冻结、已占用与剩余可冲额；
230	     * 尚无冲回单的报关单按已占用 0 派生。
231	     */
232	    @Transactional(readOnly = true)
233	    public List<ChargebackBalanceView> balances(String batchNo) {
234	        DeclarationBatch batch = batchRepo.findByNo(batchNo)
235	                .orElseThrow(() -> new NotFoundException("批次不存在: " + batchNo));
236	        Map<String, ChargebackBalance> occupied = new java.util.LinkedHashMap<>();
237	        for (ChargebackBalance b : balanceRepo.findByBatchId(batch.id())) {
238	            occupied.put(b.declarationNo(), b);
239	        }
240	        return detailRepo.findByBatchId(batch.id()).stream()
241	                .map(d -> {
242	                    ChargebackBalance b = occupied.get(d.declarationNo());
243	                    long frozen = frozenCents(d);
244	                    long used = b == null ? 0L : b.occupiedCents();
245	                    return new ChargebackBalanceView(batch.batchNo(), d.declarationNo(),
246	                            frozen, used, frozen - used);
247	                })
248	                .toList();
249	    }
250	
251	    private DeclarationBatch loadClosedBatch(String batchNo) {
252	        DeclarationBatch batch = batchRepo.findByNo(batchNo)
253	                .orElseThrow(() -> new NotFoundException("批次不存在: " + batchNo));
254	        if (batch.status() != BatchStatus.CLOSED) {
255	            throw new UnprocessableException(
256	                    "仅已结案批次允许冲回，当前状态 " + batch.status());
257	        }
258	        return batch;
259	    }
260	
261	    private ChargebackOrder loadOrder(DeclarationBatch batch, String correctionNo) {
262	        return orderRepo.findByBatchIdAndCorrectionNo(batch.id(), correctionNo)
263	                .orElseThrow(() -> new NotFoundException(
264	                        "冲回单不存在: 批次 " + batch.batchNo() + " 更正编号 " + correctionNo));
265	    }
266	
267	    private CheckDetail findBatchDetail(long batchId, String declarationNo) {
268	        return detailRepo.findByBatchId(batchId).stream()
269	                .filter(d -> d.declarationNo().equals(declarationNo))
270	                .findFirst()
