39	        postJson("/api/batches/" + batchNo + "/close",
40	                TestFixtures.requestId(prefix + "-close"), 200);
41	    }
42	
43	    @Test
44	    void concurrentApprovalsNeverExceedFrozen() throws Exception {
45	        prepareClosed("B-CC1", "CD-CC1", "cc1");
46	        // 两张待复核单各 7000，合计 14000 > 冻结 13000
47	        postJson("/api/batches/B-CC1/chargebacks",
48	                TestFixtures.chargebackSubmit("cc1-s1", "CD-CC1", "C-X", "x", 7000L, "a"), 200);
49	        postJson("/api/batches/B-CC1/chargebacks",
50	                TestFixtures.chargebackSubmit("cc1-s2", "CD-CC1", "C-Y", "x", 7000L, "a"), 200);
51	
52	        int threads = 2;
53	        CountDownLatch start = new CountDownLatch(1);
54	        ExecutorService pool = Executors.newFixedThreadPool(threads);
55	        try {
56	            java.util.List<Future<Integer>> futures = new java.util.ArrayList<>();
57	            futures.add(pool.submit(() -> {
58	                start.await();
59	                return postRaw("/api/batches/B-CC1/chargebacks/C-X/review",
60	                        TestFixtures.chargebackReview("cc1-rx", 1, "APPROVE", "bob"))
61	                        .getResponse().getStatus();
62	            }));
63	            futures.add(pool.submit(() -> {
64	                start.await();
65	                return postRaw("/api/batches/B-CC1/chargebacks/C-Y/review",
66	                        TestFixtures.chargebackReview("cc1-ry", 1, "APPROVE", "bob"))
67	                        .getResponse().getStatus();
68	            }));
69	            start.countDown();
70	
71	            int ok = 0;
72	            int rejected = 0;
73	            for (Future<Integer> f : futures) {
74	                int status = f.get(30, TimeUnit.SECONDS);
75	                if (status == 200) {
76	                    ok++;
77	                } else if (status == 422) {
78	                    rejected++;
79	                } else {
80	                    throw new AssertionError("未预期状态码 " + status);
81	                }
82	            }
83	            assertEquals(1, ok, "并发两笔批准只能有一笔占用成功");
84	            assertEquals(1, rejected, "超冲的一笔必须被业务拒绝");
