87	            assertEquals(13000L, balances.get(0).get("frozenCents").asLong());
88	            assertEquals(7000L, balances.get(0).get("occupiedCents").asLong(),
89	                    "累计占用不得超过冻结额");
90	            assertEquals(6000L, balances.get(0).get("remainingCents").asLong());
91	
92	            // 恰好一张冲回单 APPROVED 并有追缴明细，另一张回滚为 PENDING 且无追缴明细
93	            JsonNode x = getJson("/api/batches/B-CC1/chargebacks/C-X", 200);
94	            JsonNode y = getJson("/api/batches/B-CC1/chargebacks/C-Y", 200);
95	            int approved = 0;
96	            int pending = 0;
97	            for (JsonNode o : java.util.List.of(x, y)) {
98	                if ("APPROVED".equals(o.get("status").asText())) {
99	                    approved++;
