1	package com.example.rebate.testsupport;
2	
3	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
4	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
6	
7	import com.example.rebate.support.TimeService;
8	import com.fasterxml.jackson.databind.JsonNode;
9	import com.fasterxml.jackson.databind.ObjectMapper;
10	import java.util.List;
11	import org.springframework.beans.factory.annotation.Autowired;
12	import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
13	import org.springframework.boot.test.context.SpringBootTest;
14	import org.springframework.jdbc.core.JdbcTemplate;
15	import org.springframework.test.web.servlet.MockMvc;
16	import org.springframework.test.web.servlet.MvcResult;
17	
18	/**
19	 * API/H2 集成测试基类：每个用例前清空全部业务表并重置时钟，保证用例间无顺序依赖。
20	 */
21	@SpringBootTest(classes = com.example.starter.StarterApplication.class)
22	@AutoConfigureMockMvc
23	public abstract class BaseApiTest {
24	
25	    private static final List<String> TABLES = List.of(
26	            "t_chargeback_request",
27	            "t_clawback_receipt",
28	            "t_clawback_detail",
29	            "t_chargeback_order",
30	            "t_chargeback_balance",
31	            "t_idempotent_record",
32	            "t_late_event",
33	            "t_treasury_writeoff",
34	            "t_doubt",
35	            "t_check_detail",
36	            "t_invoice_registry",
37	            "t_declaration_registry",
38	            "t_batch_document",
39	            "t_declaration_batch",
40	            "t_input_invoice",
41	            "t_customs_declaration",
42	            "t_rate_library");
43	
44	    @Autowired
45	    protected MockMvc mvc;
46	
47	    @Autowired
48	    protected ObjectMapper objectMapper;
49	
50	    @Autowired
51	    protected JdbcTemplate jdbc;
52	
53	    @Autowired
54	    protected TimeService timeService;
55	
56	    @org.junit.jupiter.api.BeforeEach
57	    void cleanTables() {
58	        jdbc.update("SET REFERENTIAL_INTEGRITY FALSE");
59	        for (String table : TABLES) {
60	            jdbc.update("DELETE FROM " + table);
61	        }
62	        jdbc.update("SET REFERENTIAL_INTEGRITY TRUE");
63	        timeService.reset();
64	    }
65	
66	    /**
67	     * POST JSON 并断言期望状态码，返回解析后的响应体。
68	     */
69	    protected JsonNode postJson(String path, String json, int expectedStatus) throws Exception {
70	        MvcResult result = mvc.perform(post(path)
71	                        .contentType("application/json")
72	                        .content(json))
73	                .andExpect(status().is(expectedStatus))
74	                .andReturn();
75	        String body = result.getResponse().getContentAsString();
76	        return body.isBlank() ? null : objectMapper.readTree(body);
77	    }
78	
79	    /**
80	     * POST JSON，不预设状态码，返回原始结果（并发测试用）。
81	     */
82	    protected MvcResult postRaw(String path, String json) throws Exception {
83	        return mvc.perform(post(path)
84	                .contentType("application/json")
85	                .content(json)).andReturn();
86	    }
87	
88	    /**
89	     * GET 并断言期望状态码，返回解析后的响应体。
90	     */
91	    protected JsonNode getJson(String path, int expectedStatus) throws Exception {
92	        MvcResult result = mvc.perform(get(path))
93	                .andExpect(status().is(expectedStatus))
94	                .andReturn();
95	        String body = result.getResponse().getContentAsString();
96	        return body.isBlank() ? null : objectMapper.readTree(body);
97	    }
98	
99	    /**
100	     * 录入 V2025/V2026 两版文库。
101	     */
102	    protected void seedLibrary() throws Exception {
103	        postJson("/api/library", TestFixtures.libraryV2025("req-lib-2025"), 200);
104	        postJson("/api/library", TestFixtures.libraryV2026("req-lib-2026"), 200);
105	    }
106	}
