4	import org.springframework.stereotype.Component;
5	
6	/**
7	 * 统一时间源。生产环境返回系统 UTC 时间；测试可注入固定时刻以验证按 UTC 日界取文库版本。
8	 */
9	@Component
10	public class TimeService {
11	
12	    private volatile Instant fixed;
13	
14	    /**
15	     * 返回当前时刻（UTC）；测试固定后始终返回固定时刻。
16	     */
17	    public Instant now() {
18	        Instant f = fixed;
19	        return f != null ? f : Instant.now();
20	    }
21	
22	    /**
23	     * 仅供测试：固定时钟。
24	     */
25	    public void setFixed(Instant instant) {
26	        this.fixed = instant;
27	    }
28	
29	    /**
30	     * 仅供测试：恢复系统时钟。
