    created_at TIMESTAMP NOT NULL
);
COMMENT ON TABLE t_bank_serial_registry IS '银行流水全局互斥登记：主键保证同一真实流水只被一种入口（SINGLE 单笔回执 / AGGREGATE 汇总母凭证）使用';
