package com.example.rebate.repo;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * 银行流水全局互斥登记数据访问。主键插入即占坑：汇总母流水与旧单笔回执流水共享同一登记表，
 * 同一真实流水只能被其中一种入口占用；并发同流水在主键上串行，后到者占位失败。
 */
@Repository
public class BankSerialRegistryRepository {

    private final JdbcTemplate jdbc;

    public BankSerialRegistryRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 尝试占用流水号。
     *
     * @param source 占用入口：SINGLE 旧单笔回执 / AGGREGATE 汇总母凭证
     * @return {@code true} 占用成功；{@code false} 该流水已被任一入口占用
     */
    public boolean tryRegister(String serial, String source, Instant now) {
        try {
            jdbc.update("""
                    INSERT INTO t_bank_serial_registry (serial, source, created_at)
                    VALUES (?, ?, ?)
                    """, serial, source, Timestamp.from(now));
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** 查询流水号已被哪种入口占用；未占用返回空。 */
    public Optional<String> findSource(String serial) {
        List<String> list = jdbc.query(
                "SELECT source FROM t_bank_serial_registry WHERE serial = ?",
                (rs, rowNum) -> rs.getString("source"), serial);
        return list.stream().findFirst();
    }
}

package com.example.rebate.repo;

import com.example.rebate.domain.ClawbackAllocation;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.sql.Timestamp;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/**
 * 汇总分配行数据访问。分配行只有内部行号标识，不产生任何银行流水号；
 * 与母凭证、目标追缴明细累加在同一事务内写入。
 */
@Repository
public class ClawbackAllocationRepository {

    private static final RowMapper<ClawbackAllocation> MAPPER = new AllocationRowMapper();

    private final JdbcTemplate jdbc;

    public ClawbackAllocationRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 写入分配行，回填自增主键。 */
    public long insert(ClawbackAllocation a) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement("""
                    INSERT INTO t_clawback_allocation
                        (receipt_id, detail_id, order_id, line_no, amount_cents, created_at)
                    VALUES (?, ?, ?, ?, ?, ?)
                    """, Statement.RETURN_GENERATED_KEYS);
            ps.setLong(1, a.receiptId());
            ps.setLong(2, a.detailId());
            ps.setLong(3, a.orderId());
            ps.setInt(4, a.lineNo());
            ps.setLong(5, a.amountCents());
            ps.setTimestamp(6, Timestamp.from(a.createdAt()));
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

    public List<ClawbackAllocation> findByReceiptId(long receiptId) {
        return jdbc.query(BASE_SELECT + " WHERE receipt_id = ? ORDER BY line_no", MAPPER, receiptId);
