DeclarationBatch batch = loadClosedBatch(batchNo);

// 基本结构校验：不同更正编号、合计精确等于总额
List<AllocationLine> lines = req.allocations();
Set<String> seen = new HashSet<>();
for (line : lines) if (!seen.add(line.correctionNo())) throw new UnprocessableException("分配对象重复: " + ...);
long sum = lines.stream().mapToLong(AllocationLine::amountCents).sum();
if (sum != req.totalCents()) throw new UnprocessableException("分配合计 ... 与到账总额 ... 不一致");

String contentFp = contentFingerprint(batchNo, req);

