if (source.isPresent()) {
    return replayOrConflict(req.bankSerial(), source.get(), contentFp);
}

// 逐行校验：属于该批次、已批准、未超未收回额、版本匹配
record ResolvedLine(AllocationLine line, ChargebackOrder order, ClawbackDetail detail) {}
List<ResolvedLine> resolved = new ArrayList<>();
for (line : lines) {
    ChargebackOrder order = orderRepo.findByBatchIdAndCorrectionNo(batch.id(), line.correctionNo())
        .orElseThrow(() -> new NotFoundException("冲回单不存在于批次 " + batchNo + ": " + line.correctionNo()));
    if (order.status() != ChargebackStatus.APPROVED) throw new UnprocessableException("仅已批准冲回单可参与汇总分配，当前状态 " + order.status());
    ClawbackDetail detail = clawbackRepo.findByOrderId(order.id()).orElseThrow(...);
    long remaining = detail.approvedCents() - detail.collectedCents();
    if (line.amountCents() > remaining) throw new UnprocessableException(...超额...);
    if (detail.version() != line.expectedVersion()) throw new ConflictException(...版本...);
    resolved.add(...);
}

Instant now = timeService.now();
// 全局互斥占坑（并发权威保障）
if (!registryRepo.tryRegister(req.bankSerial(), "AGGREGATE", now)) {
    String src = registryRepo.findSource(req.bankSerial()).orElse("UNKNOWN");
    return replayOrConflict(req.bankSerial(), src, contentFp);
}

// 母凭证
long receiptId = receiptRepo.insert(new ClawbackBatchReceipt(null, batch.id(), req.bankSerial(), req.totalCents(), req.receivedAt(), contentFp, 1, now));

// 分配行 + 逐单累加（条件更新兜底并发）
List<ClawbackBatchReceiptView.AllocationView> views = new ArrayList<>();
