    ClawbackDetail after = clawbackRepo.findById(r.detail().id()).orElseThrow();
    views.add(new AllocationView(allocId, lineNo, r.order().correctionNo(), after.clawbackNo(), r.order().id(), r.line().amountCents(), after.collectedCents(), after.approvedCents() - after.collectedCents(), after.status().name(), after.version()));
