        assertEquals(5000L, queried.get("totalCents").asLong());
        assertEquals(2, queried.get("allocations").size());

        // 子单余额勾稽：已收=分配行合计；旧单笔回执为零（未拆伪银行流水）
        JsonNode orderA = getJson("/api/batches/B-AG1/chargebacks/COR-A", 200);
